<script setup lang="ts">
import {computed,onScopeDispose,reactive,ref,shallowRef,watch} from 'vue'
import {ApiError,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import {useResource} from '@/core/use-resource'
import {readTypeDevices} from '../device-types/type-devices-api'
import {useDeviceDataPreviewSample,type DeviceDataPreviewSelection} from './use-device-data-preview-sample'
import {formSubdeviceModbusRtuParser,previewSubdeviceModbusRtuParser,type SubdeviceModbusRtuParser,type SubdeviceModbusRtuPreview} from './subdevice-modbus-rtu-parser-api'
import {projectId as activeProject} from '@/core/session'
import {formModbusRtuParser,newModbusRtuForm,normalizeModbusRtuParser,modbusRtuFieldTypes,modbusRtuFunctionCodes,isModbusRtuCoil,previewModbusRtuParser,type ModbusRtuParser,type ModbusRtuPreview} from './modbus-rtu-parser-api'
const props=defineProps<{projectId:string;typeId:string;scopeKey:string;streamIdentifier:string;modelValue?:ModbusRtuParser|SubdeviceModbusRtuParser;subdeviceAddressAllowed?:boolean;allowFixedSubdeviceAddress?:boolean;disabled?:boolean;validationError?:string;top?:string}>()
const emit=defineEmits<{save:[value:ModbusRtuParser|SubdeviceModbusRtuParser];cancel:[];busy:[value:boolean]}>()
const deviceSample=useDeviceDataPreviewSample({projectId:()=>props.projectId,typeId:()=>props.typeId,scopeKey:()=>props.scopeKey,streamIdentifier:()=>props.streamIdentifier,disabled:()=>!!props.disabled})
const form=reactive(newModbusRtuForm(props.modelValue?normalizeModbusRtuParser({...props.modelValue,useSubdeviceAddress:false}):undefined)),hexMode=ref(false),testShown=ref(false),hex=ref(''),busy=ref(false),error=ref(''),result=shallowRef<ModbusRtuPreview|SubdeviceModbusRtuPreview>()
const useAddress=ref(props.modelValue?.useSubdeviceAddress??props.subdeviceAddressAllowed===true),subDeviceId=ref(''),page=ref(1),keyword=ref(''),search=ref('')
const children=useResource(signal=>readTypeDevices(props.projectId,props.typeId,{page:page.value,limit:24,keyword:search.value},signal)),addressResult=computed(()=>result.value&&'binding' in result.value?result.value as SubdeviceModbusRtuPreview:undefined)
const coilMode=computed(()=>isModbusRtuCoil(form.functionCode))
const otherBytes=computed(()=>{const n=hexMode.value?parseInt(form.dataBytes,16):Number(form.dataBytes);return Number.isInteger(n)&&n>=0&&n<=250?(hexMode.value?String(n):'0x'+n.toString(16).toUpperCase().padStart(4,'0')):''})
const reasons:Record<string,string>={MATCHED:'匹配成功',NO_MATCH_SLAVE_ADDRESS:'从机地址不匹配',NO_MATCH_FUNCTION_CODE:'功能码不匹配',NO_MATCH_DATA_BYTES:'数据字节数不匹配',REJECTED:'报文结构、校验或数值无效'}
watch(busy,value=>emit('busy',value),{immediate:true,flush:'sync'})
let alive=true,generation=0,controller:AbortController|undefined
function clearPreview(){generation++;controller?.abort();busy.value=false;result.value=undefined;error.value=''}
function close(){if(!busy.value)emit('cancel')}
function toggleMode(value:boolean){if(busy.value||props.disabled)return;const valid=hexMode.value?/^[0-9a-fA-F]{1,2}$/.test(form.dataBytes):/^(0|[1-9][0-9]{0,2})$/.test(form.dataBytes);if(!valid){error.value='请先输入有效的数据字节数';return}const n=hexMode.value?parseInt(form.dataBytes,16):Number(form.dataBytes);form.dataBytes=value?n.toString(16).toUpperCase():String(n);hexMode.value=value}
function changeFunctionCode(value:unknown){
 if(busy.value||props.disabled||typeof value!=='number'||![1,2,3,4].includes(value)||value===form.functionCode)return
 const before=coilMode.value,after=isModbusRtuCoil(value)
 if(before!==after||before&&after){form.fields=[{id:crypto.randomUUID(),propertyKey:'',offset:'0',dataType:after?'BOOL_BIT':'FLOAT32_BE',coefficient:'1'}];const count=hexMode.value?parseInt(form.dataBytes,16):Number(form.dataBytes);if(!after&&(!Number.isInteger(count)||count<2||count%2))form.dataBytes='4'}
 form.functionCode=value;clearPreview()
}
function add(){if(!busy.value&&!props.disabled&&form.fields.length<64)form.fields.push({id:crypto.randomUUID(),propertyKey:'',offset:'0',dataType:coilMode.value?'BOOL_BIT':'FLOAT32_BE',coefficient:'1'})}
function remove(index:number){if(!busy.value&&!props.disabled)form.fields.splice(index,1)}
function configuration(){if(useAddress.value&&!props.subdeviceAddressAllowed)throw new Error('仅子设备类型可使用绑定地址');if(props.subdeviceAddressAllowed&&!useAddress.value&&!props.allowFixedSubdeviceAddress)throw new Error('子设备Native须使用绑定地址，请开启使用子设备地址后保存');return useAddress.value?formSubdeviceModbusRtuParser(form,hexMode.value):formModbusRtuParser(form,hexMode.value)}
function save(){if(busy.value||props.disabled)return;try{emit('save',configuration())}catch(cause){error.value=errorMessage(cause)}}
function loadChildren(next=1){if(busy.value||props.disabled||deviceSample.context.value||!props.subdeviceAddressAllowed||!useAddress.value||!Number.isSafeInteger(next)||next<1||next>10000)return;clearPreview();subDeviceId.value='';page.value=next;children.clear();void children.reload()}
function searchChildren(){search.value=keyword.value;loadChildren()}
async function preview(){
 if(busy.value||props.disabled||props.projectId!==activeProject.value)return
 let nativeParser:ModbusRtuParser|SubdeviceModbusRtuParser,selection:DeviceDataPreviewSelection|undefined;try{selection=deviceSample.capture();nativeParser=configuration();if(selection&&!selection.member.streams.some(row=>row.identifier===props.streamIdentifier&&row.format==='HEX'))throw new Error('请选择具有已发布HEX输入流的样例设备');if(useAddress.value&&(selection?selection.member.profile.type.deviceKind!=='SUB_DEVICE':children.loading.value||!children.data.value?.items.some(row=>row.id===subDeviceId.value)))throw new Error('请选择当前类型目录中的实际子设备后预览')}catch(cause){error.value=errorMessage(cause);return}
 const s={generation,epoch:identityEpoch(),project:props.projectId,type:props.typeId,scope:props.scopeKey,stream:props.streamIdentifier,selection,previewType:selection?.member.deviceTypeId??props.typeId,child:selection?.member.deviceId??subDeviceId.value};controller?.abort();controller=new AbortController();busy.value=true;error.value='';result.value=undefined
 const current=()=>alive&&!props.disabled&&generation===s.generation&&identityEpoch()===s.epoch&&activeProject.value===s.project&&props.projectId===s.project&&props.typeId===s.type&&props.scopeKey===s.scope&&props.streamIdentifier===s.stream&&deviceSample.current(s.selection)
 try{const value=useAddress.value?await previewSubdeviceModbusRtuParser({projectId:s.project,deviceTypeId:s.previewType,scopeKey:s.scope},s.stream,formSubdeviceModbusRtuParser(form,hexMode.value),hex.value,s.child,current,controller.signal,s.selection):await previewModbusRtuParser({projectId:s.project,deviceTypeId:s.previewType,scopeKey:s.scope},s.stream,normalizeModbusRtuParser(nativeParser),hex.value,current,controller.signal,s.selection);if(current())result.value=value}catch(cause){if(current()){error.value=errorMessage(cause);if(cause instanceof ApiError&&[401,403,404].includes(cause.status))emit('cancel')}}finally{if(alive&&generation===s.generation)busy.value=false}
}
watch([()=>props.projectId,()=>props.typeId,()=>props.scopeKey,()=>props.streamIdentifier,()=>props.subdeviceAddressAllowed,()=>props.disabled],()=>{children.clear();subDeviceId.value='';clearPreview();emit('cancel')})
watch([()=>JSON.stringify(form),hex,subDeviceId,deviceSample.member],clearPreview,{flush:'sync'})
watch([useAddress,testShown],()=>{clearPreview();children.clear();subDeviceId.value='';if(!deviceSample.context.value&&useAddress.value&&testShown.value&&props.subdeviceAddressAllowed)loadChildren()},{flush:'sync'})
const dispose=onIdentityChange(()=>{children.clear();subDeviceId.value='';clearPreview();emit('cancel')});onScopeDispose(()=>{alive=false;clearPreview();dispose()})
</script>
<template><el-dialog :model-value="true" title="配置操作" :width="top?'min(1000px,94vw)':'min(920px,94vw)'" :top="top" :lock-scroll="top===undefined" :close-on-click-modal="false" :close-on-press-escape="!disabled&&!busy" :show-close="!disabled&&!busy" :before-close="close" append-to-body>
 <el-form label-position="top" :disabled="disabled||busy" class="rtu-form" @submit.prevent="save">
  <h3>匹配条件</h3><div class="rtu-match"><el-form-item label="从机地址"><el-input v-model="form.slaveAddress" aria-label="RTU从机地址" inputmode="numeric" maxlength="3"/></el-form-item><el-form-item label="功能码"><el-select :model-value="form.functionCode" aria-label="RTU功能码" @update:model-value="changeFunctionCode"><el-option v-for="[value,label] in modbusRtuFunctionCodes" :key="value" :value="value" :label="String(value).padStart(2,'0')+' '+label"/></el-select></el-form-item><el-form-item label="数据字节数"><el-switch :model-value="hexMode" active-text="Hex" inactive-text="Dec" aria-label="RTU字节数进制" @update:model-value="toggleMode($event===true)"/><el-input v-model="form.dataBytes" aria-label="RTU数据字节数" :maxlength="hexMode?2:3"><template #append>{{otherBytes}}</template></el-input></el-form-item></div>
  <el-form-item v-if="subdeviceAddressAllowed" label="使用子设备地址"><el-switch v-model="useAddress" aria-label="使用子设备地址"/></el-form-item>
  <p v-if="useAddress&&!deviceSample.context.value" class="rtu-note">保存的从机地址仍保留；执行时使用实际有效绑定的子设备地址替代。地址须为1至255的规范十进制，01不会按1解释。预览须明确选择实际子设备。</p>
  <p v-else-if="!deviceSample.context.value" class="rtu-note">从机地址1–255；248–255为协议保留值，仅兼容已有透传原帧，主动轮询仍限1–247。数据字节数{{coilMode?'为1–250':'为2–250的偶数'}}，当前按显式从机地址匹配，不使用子设备地址。</p>
  <el-form-item label="数据校验"><el-select v-model="form.crc" aria-label="RTU数据校验"><el-option value="NONE" label="不验证"/><el-option value="CRC16_MODBUS" label="CRC-16/Modbus"/></el-select></el-form-item>
  <p v-if="!deviceSample.context.value&&form.crc==='NONE'" class="rtu-note">不验证校验值，报文仍须包含完整响应结构和两个尾字节。</p>
  <h3>数据提取规则</h3><p v-if="!deviceSample.context.value" class="rtu-note">{{coilMode?'线圈地址从0起，按低位优先解析为布尔值。':'起始字节位从数据区0起算；数值按大端读取。'}}实际属性仍需符合设备类型的功能定义。</p>
  <section v-for="(row,index) in form.fields" :key="row.id" class="rtu-field" :class="{'rtu-coil-field':coilMode}"><el-form-item :label="coilMode?'线圈地址':'起始数据字节位'"><el-input v-model="row.offset" :aria-label="(coilMode?'RTU线圈地址 ':'RTU起始字节位 ')+(index+1)" inputmode="numeric" :maxlength="coilMode?4:3"/></el-form-item><el-form-item v-if="!coilMode" label="数据类型"><el-select v-model="row.dataType" :aria-label="'RTU数据类型 '+(index+1)"><el-option v-for="[value,label] in modbusRtuFieldTypes" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-form-item label="生成属性"><el-input v-model="row.propertyKey" :aria-label="'RTU生成属性 '+(index+1)" maxlength="64"/></el-form-item><el-form-item v-if="!coilMode" label="系数"><el-input v-model="row.coefficient" :aria-label="'RTU系数 '+(index+1)" maxlength="64"/></el-form-item><el-button :disabled="disabled||busy" :aria-label="'移除RTU提取行 '+(index+1)" @click="remove(index)">移除</el-button></section>
  <el-button :disabled="disabled||busy||form.fields.length>=64" @click="add">添加数据</el-button>
  <p><el-button link type="primary" :disabled="disabled||busy" @click="testShown=!testShown">测试规则</el-button></p><section v-if="testShown"><el-form-item v-if="deviceSample.context.value" label="选择模拟的设备"><el-select v-model="deviceSample.sampleDeviceId.value" filterable style="width:100%" aria-label="选择模拟的设备" placeholder="请选择设备" :disabled="disabled||busy"><el-option v-for="member in deviceSample.context.value.members" :key="member.deviceId" :value="member.deviceId" :label="member.name"/></el-select></el-form-item><el-alert v-if="deviceSample.error.value" :title="deviceSample.error.value" type="error" :closable="false"/><section v-if="useAddress&&!deviceSample.context.value" class="subdevice-preview-choice"><h4>选择用于预览的子设备</h4><el-input v-model="keyword" aria-label="预览子设备搜索" maxlength="128" placeholder="搜索本类型子设备"/><el-button :disabled="busy||children.loading.value" @click="searchChildren">搜索子设备</el-button><el-alert v-if="children.error.value" :title="errorMessage(children.error.value)" type="error" :closable="false"/><el-select v-model="subDeviceId" aria-label="预览实际子设备" :loading="children.loading.value" :disabled="busy||children.loading.value" placeholder="选择本页实际子设备"><el-option v-for="child in children.data.value?.items??[]" :key="child.id" :value="child.id" :label="child.name+' · '+child.id"/></el-select><p>第 {{page}} 页，每页24台；当前页外的设备请搜索或翻页。地址由服务端读取，不接受手填。</p><el-button :disabled="busy||children.loading.value||page<=1" @click="loadChildren(page-1)">上一页子设备</el-button><el-button :disabled="busy||children.loading.value||!children.data.value||BigInt(children.data.value.total??'0')<=BigInt(page*24)" @click="loadChildren(page+1)">下一页子设备</el-button></section><el-form-item label="Modbus RTU上报消息"><el-input v-model="hex" type="textarea" :rows="3" maxlength="2048" aria-label="RTU上报消息" placeholder="输入完整HEX帧，可用空格分隔"/></el-form-item><el-button :loading="busy" :disabled="disabled||busy" @click="preview">模拟解析</el-button><p v-if="!deviceSample.context.value" class="rtu-note">仅模拟解析样例，不创建规则或写入设备属性。</p><template v-if="result"><p role="status">{{reasons[result.reason]}}</p><template v-if="addressResult"><p aria-label="预览有效从机地址">实际从机地址：{{addressResult.effectiveSlaveAddress}}；保存配置：{{form.slaveAddress}}</p><p>实际子设备 {{deviceSample.member.value?.name??children.data.value?.items.find(child=>child.id===addressResult!.binding.subDeviceId)?.name??'已选设备'}} · 地址 {{addressResult.binding.subDeviceAddress}}</p></template><h4>设备上报属性</h4><pre aria-label="RTU解析属性">{{result.attributesJson}}</pre></template></section>
 </el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <el-alert v-if="validationError" :title="validationError" type="warning" :closable="false"/><template #footer><el-form :disabled="false"><el-button :disabled="disabled||busy" @click="close">取消</el-button><el-button type="primary" :disabled="disabled||busy" @click="save">保存</el-button></el-form></template>
</el-dialog></template>
<style scoped>.rtu-form h3{font-size:18px;font-weight:500;margin:24px 0 18px}.rtu-match{display:grid;grid-template-columns:1fr 1.2fr 1fr;gap:18px}.rtu-match :deep(.el-switch){float:right;height:20px;margin-top:-30px}.rtu-note{font-size:13px;color:var(--el-text-color-secondary);line-height:1.7}.rtu-field{display:grid;grid-template-columns:1fr 1.5fr 1.5fr 1fr auto;gap:14px;align-items:end}.rtu-coil-field{grid-template-columns:1fr 2fr auto}.rtu-field>.el-button{margin-bottom:18px}.rtu-form :deep(.el-select){width:100%}.rtu-form pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--el-fill-color-light);padding:16px;max-height:300px;overflow:auto}@media(max-width:680px){.rtu-match,.rtu-field{grid-template-columns:1fr}.rtu-field{border-bottom:1px solid var(--el-border-color);padding-bottom:12px}.rtu-coil-field{grid-template-columns:1fr}.rtu-field>.el-button{justify-self:end}}</style>
